import { Router } from 'express';
import { getLibrary, getLibraryWithVersion, saveLibrary, appendChangeLog, listChangeLog, getChangeLogEntry } from '../repo.js';
import { requireAuth, requireAdmin } from '../auth.js';
import { getCollection, newId, seedLibrary, type Library } from '@asohav/shared';
import { validateLibrary, referencedBy, diffEntry, validateSettingsPatch, validateCollectionBody, withFieldDefaults } from '../adminLogic.js';
import { wrap } from '../asyncHandler.js';

/** One record in a library collection. `Library` gives each collection its own element type, and
 *  this file's CRUD is generic over all fourteen of them by design — `getCollection()` has already
 *  established the key is real, so the widening happens once, here, rather than at every route. */
type LibRow = Record<string, unknown> & { Id: string; Name?: string };

function rowsOf(lib: Library, key: string): LibRow[] {
  return (lib as unknown as Record<string, LibRow[]>)[key];
}

export const libraryRouter = Router();

libraryRouter.use(requireAuth);

libraryRouter.get('/', wrap(async (_req, res) => {
  res.json({ library: await getLibrary() });
}));

libraryRouter.get('/validation', requireAdmin, wrap(async (_req, res) => {
  res.json({ issues: validateLibrary(await getLibrary()) });
}));

libraryRouter.get('/changelog', requireAdmin, wrap(async (_req, res) => {
  const log = await listChangeLog();
  res.json({
    entries: log.map((e) => ({ ...e, Diffs: diffEntry(e.Before, e.After) })),
  });
}));

/* Restoring a deleted record. Every delete already stored the full record as the changelog
   entry's `Before` — it just had no way back out, so "there is no undo" was true only because
   nothing read it. Restores under the record's *original* Id, which is the whole reason this is a
   route rather than the client re-POSTing the payload: a fresh Id would leave every ref that
   pointed at the deleted record still dangling. */
libraryRouter.post('/changelog/:entryId/restore', requireAdmin, wrap(async (req, res) => {
  const entry = await getChangeLogEntry(req.params.entryId);
  if (!entry) { res.status(404).json({ error: 'No such changelog entry.' }); return; }
  if (entry.Action !== 'delete') { res.status(400).json({ error: 'Only a deleted record can be restored.' }); return; }

  const col = getCollection(entry.Collection);
  if (!col) { res.status(404).json({ error: 'Unknown collection.' }); return; }

  const before = entry.Before as LibRow | null;
  if (!before || typeof before !== 'object' || !before.Id) {
    res.status(400).json({ error: 'That entry has no restorable record.' });
    return;
  }

  const { library: lib, version } = await getLibraryWithVersion();
  const arr = rowsOf(lib, col.key);
  // Re-creating an Id that is live again would give the collection two records with one Id, and
  // every ref to it would resolve arbitrarily.
  if (arr.some((x) => x.Id === before.Id)) {
    res.status(409).json({ error: `A ${col.singular.toLowerCase()} with that Id already exists.` });
    return;
  }

  arr.push(before);
  await saveLibrary(lib, version);
  await appendChangeLog({
    Who: req.user!.name,
    Action: 'create',
    Collection: col.key,
    ObjectId: before.Id,
    ObjectName: before.Name || before.Id,
    Before: null,
    After: before,
  });
  res.json({ object: before });
}));

libraryRouter.get('/:collection/:id/referenced-by', requireAdmin, wrap(async (req, res) => {
  res.json({ rows: referencedBy(await getLibrary(), req.params.collection, req.params.id) });
}));

libraryRouter.put('/settings', requireAdmin, wrap(async (req, res) => {
  const settingsError = validateSettingsPatch(req.body ?? {});
  if (settingsError) { res.status(400).json({ error: settingsError }); return; }
  const { library: lib, version } = await getLibraryWithVersion();
  const before = { ...lib.settings };
  lib.settings = { ...lib.settings, ...req.body };
  await saveLibrary(lib, version);
  await appendChangeLog({ Who: req.user!.name, Action: 'update', Collection: 'settings', ObjectId: 'settings', ObjectName: 'Game settings', Before: before, After: lib.settings });
  res.json({ settings: lib.settings });
}));

libraryRouter.post('/export', requireAdmin, wrap(async (_req, res) => {
  res.json({ exportedAt: new Date().toISOString(), app: 'asohav-content-library', library: await getLibrary() });
}));

libraryRouter.post('/import', requireAdmin, wrap(async (req, res) => {
  const incoming = (req.body?.library ?? req.body) as Library;
  if (!incoming || !incoming.virtues || !incoming.moves) {
    res.status(400).json({ error: 'Not an ASoHaV library export.' });
    return;
  }
  await saveLibrary(incoming);
  await appendChangeLog({ Who: req.user!.name, Action: 'import', Collection: 'library', ObjectId: 'library', ObjectName: 'Whole library', Before: null, After: { note: 'bulk import' } });
  res.json({ library: incoming });
}));

libraryRouter.post('/reset', requireAdmin, wrap(async (req, res) => {
  const fresh = seedLibrary();
  await saveLibrary(fresh);
  await appendChangeLog({ Who: req.user!.name, Action: 'reset', Collection: 'library', ObjectId: 'library', ObjectName: 'Whole library', Before: null, After: { note: 'reset to seed' } });
  res.json({ library: fresh });
}));

libraryRouter.post('/:collection', requireAdmin, wrap(async (req, res) => {
  const col = getCollection(req.params.collection);
  if (!col) { res.status(404).json({ error: 'Unknown collection.' }); return; }
  const body = withFieldDefaults(col.fields, req.body ?? {});
  const bodyError = validateCollectionBody(col.fields, body, { partial: false });
  if (bodyError) { res.status(400).json({ error: bodyError }); return; }
  const { library: lib, version } = await getLibraryWithVersion();
  const arr = rowsOf(lib, col.key);
  // Id last so a client-supplied one can't override the generated one — it could before 0.51.0,
  // since the spread ran the other way round.
  const obj: LibRow = { ...body, Id: newId(col.idPrefix) };
  arr.push(obj);
  await saveLibrary(lib, version);
  await appendChangeLog({ Who: req.user!.name, Action: 'create', Collection: col.key, ObjectId: obj.Id, ObjectName: obj.Name || obj.Id, Before: null, After: obj });
  res.json({ object: obj });
}));

libraryRouter.put('/:collection/:id', requireAdmin, wrap(async (req, res) => {
  const col = getCollection(req.params.collection);
  if (!col) { res.status(404).json({ error: 'Unknown collection.' }); return; }
  const bodyError = validateCollectionBody(col.fields, req.body ?? {}, { partial: true });
  if (bodyError) { res.status(400).json({ error: bodyError }); return; }
  const { library: lib, version } = await getLibraryWithVersion();
  const arr = rowsOf(lib, col.key);
  const idx = arr.findIndex((x) => x.Id === req.params.id);
  if (idx < 0) { res.status(404).json({ error: 'Not found.' }); return; }
  const before = { ...arr[idx] };
  arr[idx] = { ...arr[idx], ...req.body };
  await saveLibrary(lib, version);
  await appendChangeLog({ Who: req.user!.name, Action: 'update', Collection: col.key, ObjectId: arr[idx].Id, ObjectName: arr[idx].Name || arr[idx].Id, Before: before, After: arr[idx] });
  res.json({ object: arr[idx] });
}));

/* `?force=true` is the informed half of deleting something other records point at.
   `referencedBy()` has powered a "deleting this will break these" warning in Content Admin since
   the panel was built, but nothing enforced it — the server deleted regardless, so the warning was
   advice a client could simply not render. Blocking outright would be wrong in the other
   direction: breaking a ref is sometimes exactly what you mean to do, and the Validation panel
   surfaces the dangling ones afterward. So the default refuses and names what would break, and the
   client re-sends with `force` only after the admin confirmed through the "Delete and break N"
   dialog. A caller that never saw that dialog gets the refusal. */
libraryRouter.delete('/:collection/:id', requireAdmin, wrap(async (req, res) => {
  const col = getCollection(req.params.collection);
  if (!col) { res.status(404).json({ error: 'Unknown collection.' }); return; }
  const { library: lib, version } = await getLibraryWithVersion();
  const arr = rowsOf(lib, col.key);
  const idx = arr.findIndex((x) => x.Id === req.params.id);
  if (idx < 0) { res.json({ ok: true }); return; }

  const refs = referencedBy(lib, col.key, req.params.id);
  if (refs.length > 0 && req.query.force !== 'true') {
    res.status(409).json({
      error: `${refs.length} other record${refs.length === 1 ? '' : 's'} still reference${refs.length === 1 ? 's' : ''} this ${col.singular.toLowerCase()}. Delete it anyway to leave those references dangling.`,
      references: refs,
    });
    return;
  }
  const before = arr[idx];
  arr.splice(idx, 1);
  await saveLibrary(lib, version);
  await appendChangeLog({ Who: req.user!.name, Action: 'delete', Collection: col.key, ObjectId: before.Id, ObjectName: before.Name || before.Id, Before: before, After: null });
  res.json({ ok: true });
}));

import { supabaseAdmin } from './supabase.js';
import { pgPool } from './pgPool.js';
import type {
  AdminUserRow,
  Adventure,
  Bond,
  Campaign,
  CampaignPhase,
  CampaignStatus,
  ChangeLogEntry,
  Character,
  CharacterSheet,
  Clock,
  Encounter,
  Invite,
  InviteStatus,
  Library,
  Membership,
  Party,
  PublicUser,
  World,
} from '@asohav/shared';
import { newId, normalizeAdventure, normalizeBond, normalizeClock, normalizeEncounter, normalizeLibrary, normalizeParty, normalizeSheet, normalizeWorld, nowIso } from '@asohav/shared';

// All queries here go through the service-role client, which bypasses RLS entirely —
// authorization (membership checks, GM-only actions, admin-only writes) is enforced by the
// Express route handlers that call these functions, not by Postgres. See the design note at
// the top of supabase/migrations/0001_init.sql.

// ---------- Library (global singleton JSON blob) ----------

/** Thrown when a library write's `updated_at` precondition doesn't match — i.e. someone else
 *  saved between this request's read and its write. `status` is read by index.ts's error
 *  middleware, same as the shared `CampaignArchivedError` family. */
export class LibraryConflictError extends Error {
  readonly status = 409;
  constructor() {
    super('Someone else saved the library while you were editing. Reload and reapply your change.');
  }
}

/** Every library write is a read-modify-write of the *entire* 16-key blob, so without a
 *  precondition two admins editing unrelated records in unrelated collections silently clobber
 *  each other — last writer wins, and the changelog records both as successful. `version` is the
 *  row's `updated_at` exactly as Postgres returned it; hand it back to `saveLibrary` to make the
 *  write conditional.
 *
 *  Caveat worth knowing: this is millisecond-resolution time, not a monotonic counter, so two
 *  writes landing inside the same millisecond could both pass the check. Closing that properly
 *  needs a real version column and a migration; for a tool with a handful of admins the time
 *  precondition removes the realistic window, and it needs no schema change. */
export async function getLibraryWithVersion(): Promise<{ library: Library; version: string }> {
  const { data, error } = await supabaseAdmin.from('library').select('data, updated_at').eq('id', 'singleton').maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('Library not seeded');
  const raw = data.data as Library;
  const version = data.updated_at as string;
  const normalized = normalizeLibrary(raw);
  // Self-heal a Library row missing a field added after it was seeded, so future reads don't
  // need to repeat this — same pattern as getSheet's Recoveries/Scars backfill. Compares every
  // key rather than the six this used to name by hand: villains/npcs/locations (0.35.0) and
  // loadTiers were all added later and were never in that list, so a row missing one of them
  // re-normalized on every single read and never healed.
  const healed = (Object.keys(normalized) as (keyof Library)[]).some((k) => normalized[k] !== raw[k]);
  if (healed) {
    try {
      return { library: normalized, version: await saveLibrary(normalized, version) };
    } catch (err) {
      // Another request healed it first. Ours is equivalent, so serve it and let the caller's
      // own write fail its precondition if it has one — never fail a *read* over this.
      if (!(err instanceof LibraryConflictError)) throw err;
    }
  }
  return { library: normalized, version };
}

export async function getLibrary(): Promise<Library> {
  return (await getLibraryWithVersion()).library;
}

/** Returns the new version (the row's `updated_at` as Postgres stored it), so a caller doing
 *  several writes in a row can chain preconditions. Omitting `expectedVersion` writes
 *  unconditionally — that's the seed/import/reset path, where replacing whatever is there is the
 *  whole point; per-record edits should always pass one. */
export async function saveLibrary(lib: Library, expectedVersion?: string): Promise<string> {
  if (expectedVersion === undefined) {
    const { data, error } = await supabaseAdmin
      .from('library')
      .upsert({ id: 'singleton', data: lib, updated_at: nowIso() })
      .select('updated_at')
      .maybeSingle();
    if (error) throw error;
    return (data?.updated_at as string) ?? nowIso();
  }

  const { data, error } = await supabaseAdmin
    .from('library')
    .update({ data: lib, updated_at: nowIso() })
    .eq('id', 'singleton')
    .eq('updated_at', expectedVersion)
    .select('updated_at');
  if (error) throw error;
  if (!data || data.length === 0) throw new LibraryConflictError();
  return data[0].updated_at as string;
}

export async function libraryExists(): Promise<boolean> {
  const { data, error } = await supabaseAdmin.from('library').select('id').eq('id', 'singleton').maybeSingle();
  if (error) throw error;
  return !!data;
}

// ---------- Changelog ----------

export async function appendChangeLog(entry: Omit<ChangeLogEntry, 'Id' | 'At'>) {
  const id = newId('log');
  const at = nowIso();
  const { error } = await supabaseAdmin.from('changelog').insert({
    id,
    at,
    who: entry.Who,
    action: entry.Action,
    collection: entry.Collection,
    object_id: entry.ObjectId,
    object_name: entry.ObjectName,
    before: entry.Before,
    after: entry.After,
  });
  if (error) throw error;
}

export async function listChangeLog(limit = 200): Promise<ChangeLogEntry[]> {
  const { data, error } = await supabaseAdmin.from('changelog').select('*').order('at', { ascending: false }).limit(limit);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({
    Id: r.id,
    At: r.at,
    Who: r.who,
    Action: r.action,
    Collection: r.collection,
    ObjectId: r.object_id,
    ObjectName: r.object_name,
    Before: r.before,
    After: r.after,
  }));
}

/** One changelog entry by Id, for the restore-a-deleted-record route. Deliberately not served by
 *  filtering `listChangeLog()`'s 200-row page: a record deleted long enough ago to have scrolled
 *  off that page is exactly the one worth restoring, and filtering would report it as missing. */
export async function getChangeLogEntry(id: string): Promise<ChangeLogEntry | null> {
  const { data, error } = await supabaseAdmin.from('changelog').select('*').eq('id', id).maybeSingle();
  if (error) throw error;
  if (!data) return null;
  const r = data as any;
  return {
    Id: r.id,
    At: r.at,
    Who: r.who,
    Action: r.action,
    Collection: r.collection,
    ObjectId: r.object_id,
    ObjectName: r.object_name,
    Before: r.before,
    After: r.after,
  };
}

// ---------- Users (Supabase Auth identity + profiles) ----------

export async function listUsers(): Promise<PublicUser[]> {
  const { data, error } = await supabaseAdmin.from('profiles').select('id, name');
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ Id: r.id, Name: r.name }));
}

/** Bulk, scoped form of `listUsers` — for call sites (campaign bootstrap) that only ever need
 * a known, bounded set of users rather than every registered account. Not a replacement for
 * `listUsers` itself: `/me` needs users across all the caller's campaigns, and `/admin`
 * legitimately wants everyone (TechStackAudit.md D2). */
export async function listUsersByIds(ids: string[]): Promise<PublicUser[]> {
  if (ids.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('profiles').select('id, name').in('id', ids);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ Id: r.id, Name: r.name }));
}

/** Joins Supabase Auth's identity (email, sign-in history) with `profiles` (display name,
 * content-admin flag) — neither table alone has the full picture the admin panel needs. Not
 * paginated: `auth.admin.listUsers()` defaults to its first page (1000 users), which comfortably
 * covers this app's account volume. */
export async function listAuthUsers(): Promise<AdminUserRow[]> {
  const [{ data: authData, error: authError }, { data: profileRows, error: profileError }] = await Promise.all([
    supabaseAdmin.auth.admin.listUsers(),
    supabaseAdmin.from('profiles').select('id, name, is_admin'),
  ]);
  if (authError) throw authError;
  if (profileError) throw profileError;
  const profileById = new Map((profileRows ?? []).map((p: any) => [p.id, p]));
  return authData.users.map((u) => {
    const profile = profileById.get(u.id);
    return {
      Id: u.id,
      Email: u.email ?? '',
      Name: profile?.name ?? u.email ?? u.id,
      IsAdmin: profile?.is_admin ?? false,
      CreatedAt: u.created_at,
      LastSignInAt: u.last_sign_in_at ?? null,
    };
  });
}

/** A recovery magic-link the admin relays to the account holder out of band — there's no
 * outbound email configured for this app (see README's Auth note), so this can't send it
 * itself. Never accepts or sets a password directly; that's the point of using this over
 * `auth.admin.updateUserById({ password })`. Returns null if the user id doesn't exist. */
export async function generatePasswordResetLink(userId: string): Promise<string | null> {
  const { data, error } = await supabaseAdmin.auth.admin.getUserById(userId);
  if (error || !data.user?.email) return null;
  const { data: linkData, error: linkError } = await supabaseAdmin.auth.admin.generateLink({
    type: 'recovery',
    email: data.user.email,
  });
  if (linkError) throw linkError;
  return linkData.properties?.action_link ?? null;
}

// ---------- Campaigns / Memberships / Invites ----------

function mapCampaign(r: any): Campaign {
  return { Id: r.id, Name: r.name, GmUserId: r.gm_user_id, CreatedAt: r.created_at, Status: r.status, Phase: r.phase };
}

export async function insertCampaign(c: Campaign) {
  const { error } = await supabaseAdmin
    .from('campaigns')
    .insert({ id: c.Id, name: c.Name, gm_user_id: c.GmUserId, created_at: c.CreatedAt, status: c.Status, phase: c.Phase ?? 'PartyCreation' });
  if (error) throw error;
}

export async function getCampaign(id: string): Promise<Campaign | null> {
  const { data, error } = await supabaseAdmin.from('campaigns').select('*').eq('id', id).maybeSingle();
  if (error) throw error;
  return data ? mapCampaign(data) : null;
}

/** Bulk form of `getCampaign` — for a caller enriching a list of rows (each carrying its own
 * campaign id) that would otherwise fetch one campaign per row in a loop. See invites.ts's
 * `/mine`, which enriches every pending invite with its campaign's name. */
export async function listCampaignsByIds(ids: string[]): Promise<Campaign[]> {
  if (ids.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('campaigns').select('*').in('id', ids);
  if (error) throw error;
  return (data ?? []).map(mapCampaign);
}

export async function updateCampaignStatus(id: string, status: CampaignStatus) {
  const { error } = await supabaseAdmin.from('campaigns').update({ status }).eq('id', id);
  if (error) throw error;
}

export async function updateCampaignPhase(id: string, phase: CampaignPhase) {
  const { error } = await supabaseAdmin.from('campaigns').update({ phase }).eq('id', id);
  if (error) throw error;
}

/** Every campaign, regardless of who's a member — for the admin panel's Play Data view.
 * `listCampaignsForUser` below stays scoped to one user; this is the unscoped admin-only twin. */
export async function listAllCampaigns(): Promise<Campaign[]> {
  const { data, error } = await supabaseAdmin.from('campaigns').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return (data ?? []).map(mapCampaign);
}

/** Cascades via FK (`on delete cascade` on characters/memberships/party/bonds/invites,
 * `character_sheets` cascading further off `characters`) — see supabase/migrations/0001_init.sql. */
export async function deleteCampaign(id: string) {
  const { error } = await supabaseAdmin.from('campaigns').delete().eq('id', id);
  if (error) throw error;
}

export async function listCampaignsForUser(userId: string): Promise<(Campaign & { role: string })[]> {
  const { data, error } = await supabaseAdmin.from('memberships').select('role, campaigns(*)').eq('user_id', userId);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ ...mapCampaign(r.campaigns), role: r.role }));
}

/** The joined memberships+campaign-name/status/phase view auth.ts's `/me` route needs — only that
 * one caller, so it's its own function rather than a variant of `listMemberships`/`getCampaign`;
 * `/me` only needs a few campaign fields per membership, not a full `Campaign` row each.
 * `CampaignPhase`/`Ready` (`0.38.0`) back the Home tile's "waiting on you" hint — see
 * WorkPlan-0.38.0.md correction 3. */
export async function listMembershipsWithCampaignForUser(
  userId: string,
): Promise<(Membership & { CampaignName: string; CampaignStatus: CampaignStatus; CampaignPhase: CampaignPhase })[]> {
  const { data, error } = await supabaseAdmin
    .from('memberships')
    .select('id, user_id, campaign_id, role, character_id, ready, campaigns(name, status, phase)')
    .eq('user_id', userId);
  if (error) throw error;
  return (data ?? []).map((m: any) => ({
    Id: m.id,
    UserId: m.user_id,
    CampaignId: m.campaign_id,
    Role: m.role,
    CharacterId: m.character_id,
    Ready: m.ready ?? false,
    CampaignName: m.campaigns?.name ?? '',
    CampaignStatus: m.campaigns?.status ?? 'Active',
    // Matches campaignPhase()'s own default and 0009_campaign_phase.sql's backfill.
    CampaignPhase: m.campaigns?.phase ?? 'PartyCreation',
  }));
}

function mapMembership(r: any): Membership {
  return { Id: r.id, UserId: r.user_id, CampaignId: r.campaign_id, Role: r.role, CharacterId: r.character_id, Ready: r.ready };
}

export async function insertMembership(m: Membership) {
  const { error } = await supabaseAdmin
    .from('memberships')
    .insert({ id: m.Id, user_id: m.UserId, campaign_id: m.CampaignId, role: m.Role, character_id: m.CharacterId, ready: m.Ready ?? false });
  if (error) throw error;
}

export async function updateMembershipReady(membershipId: string, ready: boolean) {
  const { error } = await supabaseAdmin.from('memberships').update({ ready }).eq('id', membershipId);
  if (error) throw error;
}

export async function listMemberships(campaignId: string): Promise<Membership[]> {
  const { data, error } = await supabaseAdmin.from('memberships').select('*').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map(mapMembership);
}

/** Bulk form of `listMemberships`, for building every roster in one round trip (the home screen's
 * campaign tiles — see auth.ts's `/me`) instead of looping a per-campaign call. */
export async function listMembershipsForCampaigns(campaignIds: string[]): Promise<Membership[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('memberships').select('*').in('campaign_id', campaignIds);
  if (error) throw error;
  return (data ?? []).map(mapMembership);
}

export async function membershipFor(campaignId: string, userId: string): Promise<Membership | null> {
  const { data, error } = await supabaseAdmin
    .from('memberships')
    .select('*')
    .eq('campaign_id', campaignId)
    .eq('user_id', userId)
    .maybeSingle();
  if (error) throw error;
  return data ? mapMembership(data) : null;
}

export async function updateMembershipCharacter(membershipId: string, characterId: string) {
  const { error } = await supabaseAdmin.from('memberships').update({ character_id: characterId }).eq('id', membershipId);
  if (error) throw error;
}

function mapInvite(r: any): Invite {
  return { Id: r.id, CampaignId: r.campaign_id, Email: r.email, Code: r.code, SentAt: r.sent_at, Status: r.status };
}

export async function insertInvite(i: Invite) {
  const { error } = await supabaseAdmin
    .from('invites')
    .insert({ id: i.Id, campaign_id: i.CampaignId, email: i.Email, code: i.Code, sent_at: i.SentAt, status: i.Status });
  if (error) throw error;
}

export async function listInvites(campaignId: string): Promise<Invite[]> {
  const { data, error } = await supabaseAdmin.from('invites').select('*').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map(mapInvite);
}

export async function getInvite(id: string): Promise<Invite | null> {
  const { data, error } = await supabaseAdmin.from('invites').select('*').eq('id', id).maybeSingle();
  if (error) throw error;
  return data ? mapInvite(data) : null;
}

/** Case-insensitive — a code the player retyped by hand shouldn't fail on casing alone. */
export async function getInviteByCode(code: string): Promise<Invite | null> {
  const { data, error } = await supabaseAdmin.from('invites').select('*').ilike('code', code).maybeSingle();
  if (error) throw error;
  return data ? mapInvite(data) : null;
}

/** Invites addressed to `email` (case-insensitive), still awaiting a response — used to power
 * a player's "pending invites" list, which isn't scoped to a campaign the way `listInvites` is. */
export async function listPendingInvitesForEmail(email: string): Promise<Invite[]> {
  const { data, error } = await supabaseAdmin.from('invites').select('*').ilike('email', email).eq('status', 'Pending');
  if (error) throw error;
  return (data ?? []).map(mapInvite);
}

export async function updateInviteStatus(id: string, status: InviteStatus) {
  const { error } = await supabaseAdmin.from('invites').update({ status }).eq('id', id);
  if (error) throw error;
}

export async function deleteInvite(id: string) {
  const { error } = await supabaseAdmin.from('invites').delete().eq('id', id);
  if (error) throw error;
}

// ---------- Characters ----------

function mapCharacter(r: any): Character {
  // slice 5: `pronouns` defaults to '' at the column level (migration 0014), so a row from
  // before that migration ran reads back as the same empty-string default rather than undefined
  // — no separate normalize-on-read step needed the way a JSONB blob field would.
  return { Id: r.id, Name: r.name, Pronouns: r.pronouns ?? '', PlayerName: r.player_name, UserId: r.user_id, CampaignId: r.campaign_id };
}

export async function insertCharacter(c: Character) {
  const { error } = await supabaseAdmin
    .from('characters')
    .insert({ id: c.Id, name: c.Name, pronouns: c.Pronouns, player_name: c.PlayerName, user_id: c.UserId, campaign_id: c.CampaignId });
  if (error) throw error;
}

export async function listCharacters(campaignId: string): Promise<Character[]> {
  const { data, error } = await supabaseAdmin.from('characters').select('*').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map(mapCharacter);
}

/** Bulk form of `listCharacters` — see `listMembershipsForCampaigns`. */
export async function listCharactersForCampaigns(campaignIds: string[]): Promise<Character[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('characters').select('*').in('campaign_id', campaignIds);
  if (error) throw error;
  return (data ?? []).map(mapCharacter);
}

export async function getCharacter(id: string): Promise<Character | null> {
  const { data, error } = await supabaseAdmin.from('characters').select('*').eq('id', id).maybeSingle();
  if (error) throw error;
  return data ? mapCharacter(data) : null;
}

/** Every character across every campaign — for the admin panel's Play Data view. */
export async function listAllCharacters(): Promise<Character[]> {
  const { data, error } = await supabaseAdmin.from('characters').select('*');
  if (error) throw error;
  return (data ?? []).map(mapCharacter);
}

/** Cascades to the character's sheet and any Bonds it's part of (`on delete cascade`); the
 * owning membership's `character_id` is set null rather than the membership row being removed
 * (`on delete set null`) — deleting a character shouldn't also kick the player from the campaign. */
export async function deleteCharacter(id: string) {
  const { error } = await supabaseAdmin.from('characters').delete().eq('id', id);
  if (error) throw error;
}

// ---------- Character sheets ----------

/** Shared by `getSheet` and `listSheetsForCampaign`: normalizes a raw JSONB sheet and reports
 * whether the normalized form differs from what was stored, so the caller can write back a
 * self-heal for a sheet missing fields added since it was last saved — pre-0.13.0/pre-0.18.0
 * (Scars/Wealth/Treasure/Hold) or pre-V0.6-slice-1 (Strain/Statuses/HealingTrack/Boons/Banes) —
 * same pattern as campaign.ts's bootstrap route backfilling a missing Party row. */
function normalizeAndCheckHeal(raw: CharacterSheet): { normalized: CharacterSheet; needsHeal: boolean } {
  const normalized = normalizeSheet(raw);
  const needsHeal =
    normalized.Strain !== raw.Strain ||
    normalized.Statuses !== raw.Statuses ||
    normalized.HealingTrack !== raw.HealingTrack ||
    normalized.Boons !== raw.Boons ||
    normalized.Banes !== raw.Banes ||
    normalized.Scars !== raw.Scars ||
    normalized.Wealth !== raw.Wealth ||
    normalized.Treasure !== raw.Treasure ||
    normalized.Hold !== raw.Hold;
  return { normalized, needsHeal };
}

export async function getSheet(characterId: string): Promise<CharacterSheet | null> {
  const { data, error } = await supabaseAdmin.from('character_sheets').select('data, campaign_id').eq('character_id', characterId).maybeSingle();
  if (error) throw error;
  if (!data) return null;
  const { normalized, needsHeal } = normalizeAndCheckHeal(data.data as CharacterSheet);
  if (needsHeal) await saveSheet(normalized, data.campaign_id as string);
  return normalized;
}

export async function saveSheet(sheet: CharacterSheet, campaignId: string) {
  sheet.UpdatedAt = nowIso();
  const { error } = await supabaseAdmin
    .from('character_sheets')
    .upsert({ character_id: sheet.CharacterId, campaign_id: campaignId, data: sheet, updated_at: sheet.UpdatedAt });
  if (error) throw error;
}

/** One query scoped by campaign_id rather than `listCharacters` + one `getSheet` per character
 * (TechStackAudit.md D2) — `character_sheets` has carried `campaign_id` on every row since
 * migration 0005, the same column `listSheetTimestampsForCampaigns` already filters on. Keeps
 * `getSheet`'s self-heal write-back (see `normalizeAndCheckHeal`): a naive single-query rewrite
 * that dropped it would silently break the pre-0.13.0/pre-0.18.0 sheet migration path. Steady
 * state (no sheet needing a heal) is 1 round trip and 0 writes, against the previous 1 + N. */
export async function listSheetsForCampaign(campaignId: string): Promise<CharacterSheet[]> {
  const { data, error } = await supabaseAdmin.from('character_sheets').select('data, campaign_id').eq('campaign_id', campaignId);
  if (error) throw error;
  return Promise.all(
    (data ?? []).map(async (r: any) => {
      const { normalized, needsHeal } = normalizeAndCheckHeal(r.data as CharacterSheet);
      if (needsHeal) await saveSheet(normalized, r.campaign_id as string);
      return normalized;
    }),
  );
}

/** Row timestamps only, not sheet content — one of four inputs to the home screen's "last
 * played" derivation (see auth.ts's `/me`), which takes the max `UpdatedAt` across this,
 * `listPartiesForCampaigns`, `listBondsForCampaigns`, and `listEncounterTimestampsForCampaigns`
 * rather than a dedicated `campaigns.last_played_at` column that every mutating route would need
 * to touch. */
export async function listSheetTimestampsForCampaigns(campaignIds: string[]): Promise<{ CampaignId: string; UpdatedAt: string }[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('character_sheets').select('campaign_id, updated_at').in('campaign_id', campaignIds);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ CampaignId: r.campaign_id, UpdatedAt: r.updated_at }));
}

// ---------- Party ----------

export async function getParty(campaignId: string): Promise<Party | null> {
  const { data, error } = await supabaseAdmin.from('party').select('data').eq('campaign_id', campaignId).maybeSingle();
  if (error) throw error;
  if (!data) return null;
  const raw = data.data as Party;
  const normalized = normalizeParty(raw);
  // Self-heal a pre-slice-4 Party row missing PartyLevel/RapportImprovementsTaken — same pattern
  // as getSheet's Recoveries/Scars backfill.
  if (normalized.RapportImprovementsTaken !== raw.RapportImprovementsTaken || normalized.PartyLevel !== raw.PartyLevel) {
    await saveParty(normalized);
  }
  return normalized;
}

export async function saveParty(party: Party) {
  const { error } = await supabaseAdmin.from('party').upsert({ campaign_id: party.CampaignId, data: party, updated_at: nowIso() });
  if (error) throw error;
}

/** Bulk form of `getParty` — one Party per campaign, `UpdatedAt` taken from the row column (the
 * authoritative value `saveParty` sets on every write) rather than trusted from inside the JSONB
 * blob. Used for the home screen's Rapport tiles and "last played" derivation — see auth.ts's
 * `/me`. */
export async function listPartiesForCampaigns(campaignIds: string[]): Promise<Party[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('party').select('data, updated_at').in('campaign_id', campaignIds);
  if (error) throw error;
  // normalizeParty here too, not just in getParty — this is the reader behind /api/auth/me's
  // Home Rapport tiles, and it returned raw `data` until 0.50.0.
  return (data ?? []).map((r: any) => ({ ...normalizeParty(r.data as Party), UpdatedAt: r.updated_at }));
}

// ---------- Bonds ----------

export async function listBondsForCampaign(campaignId: string): Promise<Bond[]> {
  const { data, error } = await supabaseAdmin.from('bonds').select('data').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map((r: any) => normalizeBond(r.data as Bond));
}

/** Bulk form of `listBondsForCampaign` — see `listPartiesForCampaigns` for why `UpdatedAt` is
 * taken from the row column rather than the JSONB blob. */
export async function listBondsForCampaigns(campaignIds: string[]): Promise<Bond[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('bonds').select('data, updated_at').in('campaign_id', campaignIds);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ ...normalizeBond(r.data as Bond), UpdatedAt: r.updated_at }));
}

export async function insertBond(bond: Bond) {
  const { error } = await supabaseAdmin.from('bonds').insert({
    id: bond.Id,
    campaign_id: bond.CampaignId,
    character_a_id: bond.CharacterAId,
    character_b_id: bond.CharacterBId,
    data: bond,
    updated_at: nowIso(),
  });
  if (error) throw error;
}

/**
 * Runs `mutate` against a Bond row locked with `SELECT ... FOR UPDATE`, inside a real Postgres
 * transaction — via a direct `pg` connection, not `supabase-js`/PostgREST, which only offers a
 * plain check-then-write with no way to hold a row lock across the read and the write. This is
 * what actually makes propose/accept/reject race-safe: two concurrent requests against the same
 * Bond serialize on the lock instead of one silently clobbering the other.
 *
 * `mutate` should throw to abort (the transaction rolls back) rather than return an error value —
 * callers map specific thrown error types to HTTP responses. Returns null if the Bond doesn't
 * exist (also rolled back; there's nothing to lock).
 */
export async function withBondLock<T>(
  bondId: string,
  mutate: (bond: Bond) => T | Promise<T>,
): Promise<{ bond: Bond; result: T } | null> {
  const client = await pgPool.connect();
  try {
    await client.query('BEGIN');
    const { rows } = await client.query<{ data: Bond }>('SELECT data FROM bonds WHERE id = $1 FOR UPDATE', [bondId]);
    if (rows.length === 0) {
      await client.query('ROLLBACK');
      return null;
    }
    const bond = rows[0].data;
    const result = await mutate(bond);
    await client.query('UPDATE bonds SET data = $1, updated_at = now() WHERE id = $2', [JSON.stringify(bond), bondId]);
    await client.query('COMMIT');
    return { bond, result };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

// ---------- Combat ----------

export async function listEncountersForCampaign(campaignId: string): Promise<Encounter[]> {
  const { data, error } = await supabaseAdmin.from('combat_encounters').select('data').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map((r: any) => normalizeEncounter(r.data as Encounter));
}

/** Filters in Postgres on the JSONB `Status` field rather than `listEncountersForCampaign` +
 * an in-JS `.find()` (TechStackAudit.md B4/D2/C6) — a campaign accumulates Encounters forever,
 * each ended one still carrying its complete `History`, so the old form's cost grows unbounded
 * over a campaign's life. `combat_encounters` has no top-level `status` column (migration
 * 0010), so this filters the JSONB path directly (`data->>Status`) rather than adding a
 * migration — proportionate for this app's scale (a handful of Encounters per campaign over its
 * lifetime; see the perf-budget skill's "reasoning, not a hard threshold" framing), revisit if
 * that changes. `.limit(1)` rather than `.maybeSingle()` deliberately: nothing enforces at the
 * DB level that only one Encounter is ever Active (the /start route's own check is
 * application-level, not a constraint), and `.maybeSingle()` would throw on a second match where
 * the old `.find()` silently just took the first — this keeps that same tolerant behavior. */
export async function getActiveEncounter(campaignId: string): Promise<Encounter | null> {
  const { data, error } = await supabaseAdmin
    .from('combat_encounters')
    .select('data')
    .eq('campaign_id', campaignId)
    .eq('data->>Status', 'Active')
    .limit(1);
  if (error) throw error;
  return data && data.length > 0 ? normalizeEncounter(data[0].data as Encounter) : null;
}

/** Row timestamps only — see `listSheetTimestampsForCampaigns`, the same idea for the fourth
 * "last played" input. */
export async function listEncounterTimestampsForCampaigns(campaignIds: string[]): Promise<{ CampaignId: string; UpdatedAt: string }[]> {
  if (campaignIds.length === 0) return [];
  const { data, error } = await supabaseAdmin.from('combat_encounters').select('campaign_id, updated_at').in('campaign_id', campaignIds);
  if (error) throw error;
  return (data ?? []).map((r: any) => ({ CampaignId: r.campaign_id, UpdatedAt: r.updated_at }));
}

export async function saveEncounter(encounter: Encounter) {
  encounter.UpdatedAt = nowIso();
  const { error } = await supabaseAdmin
    .from('combat_encounters')
    .upsert({ id: encounter.Id, campaign_id: encounter.CampaignId, data: encounter, updated_at: encounter.UpdatedAt });
  if (error) throw error;
}

// ---------- Clocks (V0.5 slice 6, restructured V0.6 slice 6) ----------

/** Every Clock for the campaign, Open and Resolved alike — unlike Combat's "one Active Encounter
 *  at a time" shape, a campaign can have several open Clocks simultaneously (layered obstacles, a
 *  Threat running alongside an Opposition Clock), so there's no "active" filter to apply here.
 *  `normalizeClock()` translates a pre-slice-6 `Kind`/backfills new fields on every read, the same
 *  self-heal-on-read pattern `getSheet`/`getLibrary` already use. */
export async function listClocksForCampaign(campaignId: string): Promise<Clock[]> {
  const { data, error } = await supabaseAdmin.from('clocks').select('data').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map((r: any) => normalizeClock(r.data as Clock));
}

export async function saveClock(clock: Clock) {
  clock.UpdatedAt = nowIso();
  const { error } = await supabaseAdmin
    .from('clocks')
    .upsert({ id: clock.Id, campaign_id: clock.CampaignId, data: clock, updated_at: clock.UpdatedAt });
  if (error) throw error;
}

export async function deleteClock(clockId: string) {
  const { error } = await supabaseAdmin.from('clocks').delete().eq('id', clockId);
  if (error) throw error;
}

// ---------- Adventures (V0.5 slice 9) ----------

/** Every Adventure for the campaign, Active and Concluded alike — same "no active-row filter"
 *  shape as `listClocksForCampaign` above, for the same reason (a campaign may run several
 *  Adventures over its life). Only ever called for a GM membership (see campaign.ts's bootstrap
 *  route) — Adventures are GM-authored content this app doesn't surface to players. */
export async function listAdventuresForCampaign(campaignId: string): Promise<Adventure[]> {
  const { data, error } = await supabaseAdmin.from('adventures').select('data').eq('campaign_id', campaignId);
  if (error) throw error;
  return (data ?? []).map((r: any) => normalizeAdventure(r.data as Adventure));
}

export async function saveAdventure(adventure: Adventure) {
  adventure.UpdatedAt = nowIso();
  const { error } = await supabaseAdmin
    .from('adventures')
    .upsert({ id: adventure.Id, campaign_id: adventure.CampaignId, data: adventure, updated_at: adventure.UpdatedAt });
  if (error) throw error;
}

export async function deleteAdventure(adventureId: string) {
  const { error } = await supabaseAdmin.from('adventures').delete().eq('id', adventureId);
  if (error) throw error;
}

// ---------- World (V0.6 slice 8) ----------

/** One `World` per campaign, same single-row shape as `getParty` above — `normalizeWorld()`
 *  backfills any field added after a given row was written, the same self-heal-on-read pattern
 *  every other JSONB-blob type in this app uses. */
export async function getWorld(campaignId: string): Promise<World | null> {
  const { data, error } = await supabaseAdmin.from('world').select('data').eq('campaign_id', campaignId).maybeSingle();
  if (error) throw error;
  if (!data) return null;
  return normalizeWorld(data.data as World);
}

export async function saveWorld(world: World) {
  const { error } = await supabaseAdmin.from('world').upsert({ campaign_id: world.CampaignId, data: world, updated_at: nowIso() });
  if (error) throw error;
}

