  pgPool: {
    connect: vi.fn().mockResolvedValue({
      query: vi.fn().mockResolvedValue({ rows: [] }),
      release: vi.fn(),
    }),
  },
}));

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn().mockReturnValue({
      insert: vi.fn().mockResolvedValue({ data: undefined, error: null }),
    }),
  },
}));

import { supabaseAdmin } from './supabase.js';

import * as repo from './repo.js';

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('does not include an id key in the insert payload', async () => {
    await repo.appendChangeLog({
      Who: 'TestUser',
      Action: 'update',
      Collection: 'villains',
      ObjectId: 'vil-123',
      ObjectName: 'Villain Name',
      Before: { Id: 'vil-old', Name: 'Old Name' } as any,
      After: { Id: 'vil-new', Name: 'New Name' } as any,
    });

    expect(supabaseAdmin.from).toHaveBeenCalledWith('changelog');
    const insertPayload = (supabaseAdmin.from.mock.calls[0][0].insert as vi.Mock).mock.calls[0]?.[0];

    expect(insertPayload).not.toHaveProperty('id');
    expect(insertPayload).toHaveProperty('at');
    expect(insertPayload).toHaveProperty('who', 'TestUser');
    expect(insertPayload).toHaveProperty('action', 'update');
    expect(insertPayload).toHaveProperty('collection', 'villains');
    expect(insertPayload).toHaveProperty('object_id', 'vil-123');
    expect(insertPayload).toHaveProperty('object_name', 'Villain Name');
    expect(insertPayload).toHaveProperty('before');
    expect(insertPayload).toHaveProperty('after');
  });

  it('includes exactly the columns the changelog table declares, correctly mapped to snake_case', async () => {
    await repo.appendChangeLog({
      Who: 'GM',
      Action: 'delete',
      Collection: 'encounters',
      ObjectId: 'enc-456',
      ObjectName: 'Encounter Name',
      Before: { Status: 'Active' } as any,
      After: null,
    });

    expect(supabaseAdmin.from).toHaveBeenCalledWith('changelog');
    const insertPayload = (supabaseAdmin.from.mock.calls[0][0].insert as vi.Mock).mock.calls[0]?.[0];

    expect(insertPayload).not.toHaveProperty('id');
    expect(insertPayload).toHaveProperty('at');
    expect(insertPayload).toHaveProperty('who', 'GM');
    expect(insertPayload).toHaveProperty('action', 'delete');
    expect(insertPayload).toHaveProperty('collection', 'encounters');
    expect(insertPayload).toHaveProperty('object_id', 'enc-456');
    expect(insertPayload).toHaveProperty('object_name', 'Encounter Name');
    expect(insertPayload).toHaveProperty('before');
    expect(insertPayload).toHaveProperty('after');
  });

  it('propagates errors from the insert call rather than swallowing them', async () => {
    const mockError = new Error('Insert failed');
    (supabaseAdmin.from as any).mockImplementation(() => ({
      insert: vi.fn().mockResolvedValue({ data: undefined, error: mockError }),
    }));

    await expect(repo.appendChangeLog({
      Who: 'Test',
      Action: 'create',
      Collection: 'test',
      ObjectId: '1',
      ObjectName: 'Test Object',
      Before: null as any,
      After: null as any,
    })).rejects.toThrow(mockError);
  });
});

